            return 0;
        }

        // number of GET calls with timestamp in (t - 300000, t]
        long getCount(long t) {
            return 0;
        }
    }

    static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    static String fmt(long c) {
        long g = gcd(c, 300);
        return (c / g) + "/" + (300 / g);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer tk = new StringTokenizer(all.toString());
        int q = Integer.parseInt(tk.nextToken());
        Store store = new Store();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String op = tk.nextToken();
            long t = Long.parseLong(tk.nextToken());
            if (op.equals("PUT")) {
                String key = tk.nextToken();
                String value = tk.nextToken();
                store.put(t, key, value);
            } else if (op.equals("GET")) {
                sb.append(store.get(t, tk.nextToken())).append("\n");
            } else if (op.equals("PUT_LOAD")) {
                sb.append(fmt(store.putCount(t))).append("\n");
            } else {
                sb.append(fmt(store.getCount(t))).append("\n");
            }
        }
        System.out.print(sb);
    }
}

