def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'

    def word(lo, hi):
        return ''.join(rng.choice(letters) for _ in range(rng.randint(lo, hi)))

    def build(q, steps, keys, vals, probs=(0.3, 0.3, 0.2, 0.2)):
        t = rng.randint(0, 5)
        ops = []
        for _ in range(q):
            t += rng.choice(steps)
            r = rng.random()
            if r < probs[0]:
                ops.append(f"PUT {t} {rng.choice(keys)} {rng.choice(vals)}")
            elif r < probs[0] + probs[1]:
                ops.append(f"GET {t} {rng.choice(keys)}")
            elif r < probs[0] + probs[1] + probs[2]:
                ops.append(f"PUT_LOAD {t}")
            else:
                ops.append(f"GET_LOAD {t}")
        ops[-1] = f"GET_LOAD {t}"
        return str(len(ops)) + '\n' + '\n'.join(ops)

    tests = [
        "1\nGET_LOAD 0",
        "1\nPUT_LOAD 5",
        "2\nGET 7 a\nGET_LOAD 7",
        "7\nPUT 1000 a x\nGET 2000 a\nGET 3000 b\nPUT_LOAD 4000\nGET_LOAD 4000\nPUT_LOAD 301000\nGET_LOAD 301000",
        "6\nPUT 10 k v\nPUT 10 k w\nPUT 10 j v\nGET 10 k\nPUT_LOAD 10\nGET_LOAD 300009",
        "5\nPUT 0 a b\nPUT_LOAD 299999\nPUT_LOAD 300000\nGET 300000 a\nGET_LOAD 300000",
        "4\nPUT 5 a b\nPUT 300005 a c\nPUT_LOAD 300005\nGET 300005 a",
    ]
    for q in (3, 5, 6, 8, 10, 10, 10, 10):
        tests.append(build(q, [0, 0, 1, 5, 150000, 299999, 300000, 300001], ['a', 'b', 'c'], ['x', 'yy', 'z']))
    for q in (8, 10, 10):
        tests.append(build(q, [0, 1, 2], ['k', 'l'], ['p', 'q']))
    tests.append(build(1000, [0, 0, 1, 50, 5000, 100000, 300000], [word(1, 3) for _ in range(30)], [word(1, 4) for _ in range(30)]))
    keys = [word(2, 6) for _ in range(800)]
    vals = [word(2, 6) for _ in range(800)]
    Q = 50000
    tests.append(build(Q, [0, 1, 1, 2, 3], keys, vals))
    tests.append(build(Q, [0, 5, 10, 20, 30], keys, vals))
    tests.append(build(Q, [0, 100, 600, 1200], keys, vals, (0.2, 0.2, 0.3, 0.3)))
